import { notFound } from "next/navigation";
import { getSecureVendorOfferPage } from "@/lib/dispatch/vendor-offer-portal-repository";
import VendorOfferResponse from "./VendorOfferResponse";
const money=(n:number)=>`Rs. ${(n/100).toLocaleString("en-PK")}`;
export default async function Page({params}:{params:Promise<{token:string}>}){const{token}=await params;let offer;try{offer=await getSecureVendorOfferPage(token)}catch{return notFound()}return <main className="min-h-screen bg-slate-100 p-4"><section className="mx-auto max-w-lg rounded-2xl bg-white p-5 shadow"><p className="text-xs font-black uppercase tracking-widest text-green-700">RentKA secure vendor trip offer</p><h1 className="mt-1 text-2xl font-black">{offer.bookingId}</h1><p className="text-sm font-bold">For {offer.vendorName}</p><div className="my-5 grid gap-3 rounded-xl bg-slate-50 p-4 text-sm"><p><b>Date / Time:</b> {offer.travelDate} · {offer.pickupTime}</p><p><b>Pickup area:</b> {offer.generalPickupArea}</p><p><b>Destination / Usage:</b> {offer.generalDestination}</p><p><b>Vehicle requirement:</b> {offer.vehicleRequirement}</p><p><b>Package:</b> {offer.packageInformation}</p><p className="text-lg"><b>Offered vendor payout:</b> {money(offer.offeredPayoutMinor)}</p><p><b>Respond before:</b> {offer.offerExpiresAt}</p><p><b>RentKA support:</b> {offer.supportPhone}</p></div>{offer.latestResponse&&<p className="mb-4 rounded bg-blue-50 p-3 text-sm">Response: <b>{offer.latestResponse.kind.replaceAll("_"," ")}</b>. {offer.latestResponse.kind==="accepted"?"Awaiting fulfillment proposal and RentKA assignment.":"RentKA will review it."}</p>}{offer.currentProposal&&<p className="mb-4 rounded bg-green-50 p-3 text-sm"><b>Current proposal:</b> {offer.currentProposal.driverName} · {offer.currentProposal.vehicleLabel}. Awaiting RentKA assignment.</p>}<VendorOfferResponse token={token} offer={offer}/></section></main>}
